window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4516a6bf4c192609"]={"versions": [{"id": "FIG-4516a6bf4c192609", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponenten- bzw. Klassendiagramm zur Darstellung der Schnittstellenarchitektur des Functional Clusters <code>Firewall</code> innerhalb der AUTOSAR Adaptive Platform (EXP_SWArchitecture). Es zeigt die Interaktion einer adaptiven Anwendung mit der Firewall über eine standardisierte Dienstschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application</strong>: Komponenten-Entität (symbolisiert als UML-Komponente), die als Client/Konsument agiert.\n</li><li><strong>«aapFunctionalCluster» Firewall (daemon-based)</strong>: Funktioneller Cluster der AUTOSAR Adaptive Platform, realisiert als Daemon-Prozess.\n</li><li><strong>«aapAPI, aapPortInterface» FirewallStateSwitchInterface</strong>: Schnittstelle mit der Operation <code>+ SwitchFirewallState()</code>, die vom Functional Cluster Firewall implementiert (Realisierungsbeziehung mit gestricheltem Pfeil und geschlossener, nicht ausgefüllter Pfeilspitze) und von der Adaptive Application über eine Abhängigkeitsbeziehung (gestrichelter Pfeil mit offener Spitze) mit den Stereotypen <code>«use»</code> und <code>«aapRequiredPort»</code> genutzt wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchrone oder asynchrone Methodeninteraktion: Eine Adaptive Application initiiert über ihren benötigten Port (<code>«aapRequiredPort»</code>) den Aufruf der Operation <code>SwitchFirewallState()</code> an der Schnittstelle <code>FirewallStateSwitchInterface</code>, um den Zustand der Firewall im Daemon-basierten Functional Cluster umzuschalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturrelevante Schnittstellendefinition für Entwickler von Adaptive Applications, die Firewall-Zustände steuern müssen. Der Dienst ist als <code>«aapAPI»</code> und <code>«aapPortInterface»</code> ausgeprägt; die tatsächliche Realisierung erfolgt entkoppelt im Firewall-Daemon. Client-Anwendungen binden die Schnittstelle über einen Required Port an.</p>"}, {"id": "FIG-0ae668cf932d5a47", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponenten- bzw. Klassendiagramm zur Darstellung der Schnittstellenarchitektur des Functional Clusters <code>Firewall</code> innerhalb der AUTOSAR Adaptive Platform (EXP_SWArchitecture). Es zeigt die Interaktion einer adaptiven Anwendung mit der Firewall über eine standardisierte Dienstschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application</strong>: Komponenten-Entität (symbolisiert als UML-Komponente), die als Client/Konsument agiert.\n</li><li><strong>«aapFunctionalCluster» Firewall (daemon-based)</strong>: Funktioneller Cluster der AUTOSAR Adaptive Platform, realisiert als Daemon-Prozess.\n</li><li><strong>«aapAPI, aapPortInterface» FirewallStateSwitchInterface</strong>: Schnittstelle mit der Operation <code>+ SwitchFirewallState()</code>, die vom Functional Cluster Firewall implementiert (Realisierungsbeziehung mit gestricheltem Pfeil und geschlossener, nicht ausgefüllter Pfeilspitze) und von der Adaptive Application über eine Abhängigkeitsbeziehung (gestrichelter Pfeil mit offener Spitze) mit den Stereotypen <code>«use»</code> und <code>«aapRequiredPort»</code> genutzt wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchrone oder asynchrone Methodeninteraktion: Eine Adaptive Application initiiert über ihren benötigten Port (<code>«aapRequiredPort»</code>) den Aufruf der Operation <code>SwitchFirewallState()</code> an der Schnittstelle <code>FirewallStateSwitchInterface</code>, um den Zustand der Firewall im Daemon-basierten Functional Cluster umzuschalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturrelevante Schnittstellendefinition für Entwickler von Adaptive Applications, die Firewall-Zustände steuern müssen. Der Dienst ist als <code>«aapAPI»</code> und <code>«aapPortInterface»</code> ausgeprägt; die tatsächliche Realisierung erfolgt entkoppelt im Firewall-Daemon. Client-Anwendungen binden die Schnittstelle über einen Required Port an.</p>"}, {"id": "FIG-f5868505cb8a6e21", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponenten- bzw. Klassendiagramm zur Darstellung der Schnittstellenarchitektur des Functional Clusters <code>Firewall</code> innerhalb der AUTOSAR Adaptive Platform (EXP_SWArchitecture). Es zeigt die Interaktion einer adaptiven Anwendung mit der Firewall über eine standardisierte Dienstschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application</strong>: Komponenten-Entität (symbolisiert als UML-Komponente), die als Client/Konsument agiert.\n</li><li><strong>«aapFunctionalCluster» Firewall (daemon-based)</strong>: Funktioneller Cluster der AUTOSAR Adaptive Platform, realisiert als Daemon-Prozess.\n</li><li><strong>«aapAPI, aapPortInterface» FirewallStateSwitchInterface</strong>: Schnittstelle mit der Operation <code>+ SwitchFirewallState()</code>, die vom Functional Cluster Firewall implementiert (Realisierungsbeziehung mit gestricheltem Pfeil und geschlossener, nicht ausgefüllter Pfeilspitze) und von der Adaptive Application über eine Abhängigkeitsbeziehung (gestrichelter Pfeil mit offener Spitze) mit den Stereotypen <code>«use»</code> und <code>«aapRequiredPort»</code> genutzt wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchrone oder asynchrone Methodeninteraktion: Eine Adaptive Application initiiert über ihren benötigten Port (<code>«aapRequiredPort»</code>) den Aufruf der Operation <code>SwitchFirewallState()</code> an der Schnittstelle <code>FirewallStateSwitchInterface</code>, um den Zustand der Firewall im Daemon-basierten Functional Cluster umzuschalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturrelevante Schnittstellendefinition für Entwickler von Adaptive Applications, die Firewall-Zustände steuern müssen. Der Dienst ist als <code>«aapAPI»</code> und <code>«aapPortInterface»</code> ausgeprägt; die tatsächliche Realisierung erfolgt entkoppelt im Firewall-Daemon. Client-Anwendungen binden die Schnittstelle über einen Required Port an.</p>"}, {"id": "FIG-cc6735f815148905", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponenten- bzw. Klassendiagramm zur Darstellung der Schnittstellenarchitektur des Functional Clusters <code>Firewall</code> innerhalb der AUTOSAR Adaptive Platform (EXP_SWArchitecture). Es zeigt die Interaktion einer adaptiven Anwendung mit der Firewall über eine standardisierte Dienstschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application</strong>: Komponenten-Entität (symbolisiert als UML-Komponente), die als Client/Konsument agiert.\n</li><li><strong>«aapFunctionalCluster» Firewall (daemon-based)</strong>: Funktioneller Cluster der AUTOSAR Adaptive Platform, realisiert als Daemon-Prozess.\n</li><li><strong>«aapAPI, aapPortInterface» FirewallStateSwitchInterface</strong>: Schnittstelle mit der Operation <code>+ SwitchFirewallState()</code>, die vom Functional Cluster Firewall implementiert (Realisierungsbeziehung mit gestricheltem Pfeil und geschlossener, nicht ausgefüllter Pfeilspitze) und von der Adaptive Application über eine Abhängigkeitsbeziehung (gestrichelter Pfeil mit offener Spitze) mit dem Stereotyp <code>«use»</code> genutzt wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchrone oder asynchrone Methodeninteraktion: Eine Adaptive Application initiiert über die Abhängigkeit (<code>«use»</code>) den Aufruf der Operation <code>SwitchFirewallState()</code> an der Schnittstelle <code>FirewallStateSwitchInterface</code>, um den Zustand der Firewall im Daemon-basierten Functional Cluster umzuschalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturrelevante Schnittstellendefinition für Entwickler von Adaptive Applications, die Firewall-Zustände steuern müssen. Der Dienst ist als <code>«aapAPI»</code> und <code>«aapPortInterface»</code> ausgeprägt; die tatsächliche Realisierung erfolgt entkoppelt im Firewall-Daemon. Client-Anwendungen binden die Schnittstelle über eine Verwendungsbeziehung (<code>«use»</code>) an.</p>"}], "trans": [{"from": "FIG-4516a6bf4c192609", "to": "FIG-0ae668cf932d5a47", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0ae668cf932d5a47", "to": "FIG-f5868505cb8a6e21", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f5868505cb8a6e21", "to": "FIG-cc6735f815148905", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Abhängigkeitspfeil zwischen <code>Adaptive Application</code> und <code>FirewallStateSwitchInterface</code>: Stereotyp <code>«aapRequiredPort»</code> entfernt, Stereotyp <code>«use»</code> verbleibt.\n</li></ul>"}]};
